3	import TruncatedText from '../TruncatedText'
4	import { LocalFile } from './useFileTree'
5	import { DriveAssignment, DriveAssignmentsHandle, PickerTarget } from './useDriveAssignments'
6	import { InclusionHandle } from './useInclusion'
7	import { OpenDriveFolder } from '../../../wailsjs/go/main/App'
8	import { handlePromiseRejection } from '../../lib/globalErrorHandler'
9	import { formatFileSize } from '../../utils'
10	import styles from './FileList.module.css'
11	
12	interface Props {
13	  files: LocalFile[]
14	  assignments: DriveAssignmentsHandle
15	  inheritedAssignment: DriveAssignment | null
16	  inclusion: InclusionHandle
17	  locked: boolean
18	  onPick: (target: PickerTarget) => void
19	  selectedPath: string | null
20	  onSelectFile: (file: LocalFile) => void
21	}
