23	export default function FileList({ files, assignments, inheritedAssignment, inclusion, locked, onPick, selectedPath, onSelectFile }: Props) {
24	  return (
25	    <Stack gap={10} mt={4}>
26	      {files.map(file => {
27	        const own = assignments.fileOverrides.get(file.path) ?? null
28	        const effective = own ?? inheritedAssignment
29	        const previewable = file.isPdf && !file.corrupt
30	        const detail = [
31	          file.corrupt ? 'Unreadable' : file.isPdf ? `${file.pageCount} pages` : null,
32	          formatFileSize(file.sizeBytes),
33	        ].filter(Boolean).join(' · ')
34	        return (
35	          <Box
36	            key={file.path}
37	            pl={4}
38	            py={2}
39	            onClick={() => previewable && onSelectFile(file)}
40	            className={`${styles.row} ${previewable ? styles.rowClickable : styles.rowNotClickable} ${selectedPath === file.path ? styles.rowSelected : ''}`}
41	          >
42	            <Group gap={8} wrap="nowrap" align="center">
43	              <Checkbox
44	                size="xs"
45	                checked={inclusion.isFileSelected(file.path)}
46	                disabled={locked}
47	                onChange={() => inclusion.toggleFile(file.path)}
48	                aria-label={`Include ${file.name} in upload`}
49	              />
50	              <Group gap={4} wrap="nowrap" className={styles.nameGroup}>
51	                {file.isPdf && (
52	                  <Badge size="xs" variant="light" color="red" radius="sm" className={styles.pdfBadge}>
53	                    PDF
54	                  </Badge>
55	                )}
56	                <TruncatedText label={file.name} size="sm" c={file.corrupt ? 'red' : undefined}>
57	                  {file.isPdf ? '' : '📄 '}{file.name}
58	                </TruncatedText>
59	                {file.corrupt && (
60	                  <Tooltip label="Could not read this file — it may be corrupt or not a valid PDF">
61	                    <span>⚠️</span>
62	                  </Tooltip>
63	                )}
64	              </Group>
65	              <DriveAssignmentField
66	                label={file.name}
67	                assignment={effective}
68	                isOwn={own !== null}
69	                locked={locked}
70	                onPick={() => onPick({ type: 'file', path: file.path })}
71	                onClear={() => assignments.clearFileOverride(file.path)}
72	                onOpen={() => effective && OpenDriveFolder(effective.driveFolderId).catch(handlePromiseRejection('Opening Drive folder failed'))}
73	              />
74	            </Group>
75	            <Text size="xs" c="dimmed" mt={2}>
