import { useEffect, useState } from 'react'
import { Box, Button, Group, Loader, Modal, Text } from '@mantine/core'
import { ListDriveFolder } from '../../../wailsjs/go/main/App'
import { DriveAssignment } from './useDriveAssignments'
import styles from './DriveFolderPickerModal.module.css'

interface DriveFolder {
  id: string
  name: string
}

const ROOT: DriveFolder = { id: 'root', name: '/' }
const INDENT_PER_LEVEL = 16

interface DriveTreeNodeProps {
  item: DriveFolder
  path: string
  selectedId: string | null
  onSelect: (item: DriveFolder, path: string) => void
  defaultExpanded?: boolean
}

function DriveTreeNode({ item, path, selectedId, onSelect, defaultExpanded }: DriveTreeNodeProps) {
  const [expanded, setExpanded] = useState(defaultExpanded ?? false)
  const [children, setChildren] = useState<DriveFolder[] | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const load = async () => {
    setLoading(true)
    setError(null)
    try {
      const items = await ListDriveFolder(item.id)
      setChildren(items.filter(i => i.isFolder).map(i => ({ id: i.id, name: i.name })))
    } catch (e) {
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (defaultExpanded && children === null) load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const toggle = () => {
    if (!expanded && children === null) load()
    setExpanded(prev => !prev)
  }

  return (
    <Box>
      <Group gap={4} wrap="nowrap">
        <button
          type="button"
          onClick={toggle}
          aria-expanded={expanded}
          aria-label={expanded ? `Collapse ${item.name}` : `Expand ${item.name}`}
          className={styles.toggleButton}
        >
          {loading ? <Loader size={10} /> : <Text size="xs" c="dimmed">{expanded ? '▼' : '▶'}</Text>}
        </button>
        <button
          type="button"
          onClick={() => onSelect(item, path)}
          className={`${styles.selectButton} ${item.id === selectedId ? styles.selectButtonSelected : ''}`}
        >
          <Text size="sm" fw={item.id === selectedId ? 600 : 400}>📁 {item.name}</Text>
        </button>
      </Group>
      {error && <Text size="xs" c="red" pl={INDENT_PER_LEVEL + 6}>{error}</Text>}
      {expanded && children && (
        <Box pl={INDENT_PER_LEVEL}>
          {children.length === 0
            ? <Text size="xs" c="dimmed" pl={6}>No subfolders</Text>
            : children.map(child => (
                <DriveTreeNode
                  key={child.id}
                  item={child}
                  path={path.endsWith('/') ? `${path}${child.name}` : `${path}/${child.name}`}
                  selectedId={selectedId}
                  onSelect={onSelect}
                />
              ))}
        </Box>
      )}
    </Box>
  )
}

interface Props {
  opened: boolean
  onClose: () => void
  onSelect: (folder: DriveAssignment) => void
}

export default function DriveFolderPickerModal({ opened, onClose, onSelect }: Props) {
  const [selected, setSelected] = useState<{ id: string; name: string; path: string } | null>(null)

  useEffect(() => {
    if (!opened) setSelected(null)
  }, [opened])

  const confirm = () => {
    if (!selected) return
    onSelect({ driveFolderId: selected.id, path: selected.path })
    onClose()
  }

  return (
    <Modal opened={opened} onClose={onClose} title="Choose a Drive folder" size="md">
      <Box className={styles.treeScroll}>
        <DriveTreeNode
          item={ROOT}
          path={ROOT.name}
          selectedId={selected?.id ?? null}
          onSelect={(item, path) => setSelected({ id: item.id, name: item.name, path })}
          defaultExpanded
        />
      </Box>
      <Group justify="flex-end" mt="md">
        <Button variant="default" onClick={onClose}>Cancel</Button>
        <Button disabled={!selected} onClick={confirm}>
          {selected ? `Select "${selected.name}"` : 'Select'}
        </Button>
      </Group>
    </Modal>
  )
}

import { useState, useCallback } from 'react'
import { PickFolder, ScanLocalRoot } from '../../../wailsjs/go/main/App'

export interface LocalFile {
  path: string
  name: string
  sizeBytes: number
  isPdf: boolean
  pageCount: number
  corrupt: boolean
}

export interface LocalFileGroup {
  name: string
  files: LocalFile[]
  subgroups: LocalFileGroup[]
}

// Flat, ordered list of every file in the tree (a group's own files, then
// its subgroups' files, recursively). Shared by the upload worker (order to
// process files in), the upload modal's per-group rollup counts, and the
// "every file in this group is done" check driving the Open-in-Drive link —
// one traversal so they can't drift out of sync on how they handle nesting.
export function flattenFiles(group: LocalFileGroup): LocalFile[] {
  return [...group.files, ...group.subgroups.flatMap(flattenFiles)]
}

export interface FileTreeHandle {
  root: string | null
  tree: LocalFileGroup | null
  loading: boolean
  error: string | null
  // Resolves to whether a folder was actually picked (false if the user
  // cancelled the dialog), so callers know when a fresh root replaced the
  // previous one and any per-root state (e.g. the upload queue) should reset.
  pickRoot: () => Promise<boolean>
}

export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [tree, setTree] = useState<LocalFileGroup | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pickRoot = useCallback(async () => {
    const folder = await PickFolder('Choose Root Folder')
    if (!folder) return false

    setRoot(folder)
    setLoading(true)
    setError(null)
    try {
      setTree(await ScanLocalRoot(folder))
    } catch (e) {
      setTree(null)
      setError(String(e))
    } finally {
      setLoading(false)
    }
    return true
  }, [])

  return { root, tree, loading, error, pickRoot }
}

import { useState, useCallback, useEffect } from 'react'
import { LocalFileGroup, flattenFiles } from './useFileTree'

export type GroupSelectionState = 'checked' | 'unchecked' | 'indeterminate'

export interface InclusionHandle {
  isFileSelected: (path: string) => boolean
  getGroupState: (group: LocalFileGroup) => GroupSelectionState
  toggleFile: (path: string) => void
  toggleGroup: (group: LocalFileGroup) => void
  selectAll: () => void
  selectNone: () => void
}

// Tracks which files are excluded from the upload, keyed by path. A
// subfolder's checkbox state is derived from its descendant files rather
// than stored separately, so the "fully selected/unselected collapses all
// the way up the tree" behavior falls out of the derivation for free
// instead of needing explicit upward-propagation bookkeeping.
export function useInclusion(tree: LocalFileGroup | null): InclusionHandle {
  const [deselected, setDeselected] = useState<Set<string>>(new Set())

  // Resets to fully-selected on every fresh scan — deliberately not
  // persisted, unlike Drive folder mappings.
  useEffect(() => {
    setDeselected(new Set())
  }, [tree])

  const isFileSelected = useCallback((path: string) => !deselected.has(path), [deselected])

  const getGroupState = useCallback((group: LocalFileGroup): GroupSelectionState => {
    const files = flattenFiles(group)
    if (files.length === 0) return 'checked'
    const selectedCount = files.filter(f => !deselected.has(f.path)).length
    if (selectedCount === 0) return 'unchecked'
    if (selectedCount === files.length) return 'checked'
    return 'indeterminate'
  }, [deselected])

  const toggleFile = useCallback((path: string) => {
    setDeselected(prev => {
      const next = new Set(prev)
      if (next.has(path)) next.delete(path); else next.add(path)
      return next
    })
  }, [])

  // Indeterminate or fully-unselected groups select all descendants; a
  // fully-selected group deselects all descendants. Decided from the
  // group's own current state rather than the checkbox's native toggle, so
  // clicking an indeterminate checkbox always selects, never clears.
  const toggleGroup = useCallback((group: LocalFileGroup) => {
    const files = flattenFiles(group)
    setDeselected(prev => {
      const allSelected = files.every(f => !prev.has(f.path))
      const next = new Set(prev)
      for (const f of files) {
        if (allSelected) next.add(f.path); else next.delete(f.path)
      }
      return next
    })
  }, [])

  const selectAll = useCallback(() => setDeselected(new Set()), [])

  const selectNone = useCallback(() => {
    setDeselected(new Set(tree ? flattenFiles(tree).map(f => f.path) : []))
  }, [tree])

  return { isFileSelected, getGroupState, toggleFile, toggleGroup, selectAll, selectNone }
}

